# New preservation attempt after explicit user-authorized checkpoint cleanup.
# Keeps the original 50-checkpoint failure intact; never boots/restores/deletes/replays.
[CmdletBinding()]param(
    [Parameter(Mandatory)][string]$CleanupReceipt,
    [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$CleanupReceiptSha256
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$workspace='D:\code\ntfs2refs';$base=Join-Path $workspace '.lab\hyperv\streaming-v2-20261027';$run='94eebb1101354d2ca42c2f8f0608f6a0';$case=Join-Path $base ('managed-compact-interrupt-20261028-'+$run);$root=Join-Path $case 'partial-after-cleanup'
$id=[guid]'2401593c-4b30-472e-9b6d-c9534cbaa599';$keep=@('9e63e9d2-a0e4-408f-87b5-26d31fbdcc24','219e3abf-4289-4e16-b27f-2b4d32ac619c');$parent=[guid]$keep[0];$name='managed-partial94'
function Need([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
function Json([string]$Path,[string]$Pin=''){$m=Get-Item -LiteralPath $Path -Force;Need (-not$m.PSIsContainer -and -not($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $m.Length -gt 0 -and $m.Length -le 4MB) 'Bounded ordinary host JSON required.';$a=$m.Directory;while($null -ne $a){Need (-not($a.Attributes -band [IO.FileAttributes]::ReparsePoint)) 'Reparse host JSON ancestry refused.';$a=$a.Parent};if($Pin){Need ((Get-FileHash -LiteralPath $Path).Hash.ToLowerInvariant() -ceq $Pin) 'Host evidence pin differs.'};Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}
function Utc($Value){if($Value -is [DateTime]){Need ($Value.Kind -ne [DateTimeKind]::Unspecified) 'Timestamp timezone is unspecified.';return $Value.ToUniversalTime()};if($Value -is [DateTimeOffset]){return $Value.UtcDateTime};[DateTimeOffset]::Parse([string]$Value,[Globalization.CultureInfo]::InvariantCulture).UtcDateTime}
function Save([string]$Name,$Value){$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 14));Need ($bytes.Length -le 4MB) 'Receipt exceeds4MiB.';$f=[IO.File]::Open((Join-Path $root $Name),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()}}
Need (-not(Test-Path -LiteralPath $root)) 'Post-cleanup preservation has state; inspect without repeating creation.'
Need ([IO.Path]::GetFullPath($CleanupReceipt) -ceq (Join-Path $base 'checkpoint-cleanup-20261029\result.json')) 'Exact authorized cleanup result path required.';$cleanup=Json $CleanupReceipt $CleanupReceiptSha256
Need ($cleanup.success -eq $true -and [guid]$cleanup.vm_id -eq $id -and $cleanup.remaining_count -eq 2 -and @($cleanup.remaining_ids).Count -eq 2 -and @($cleanup.remaining_ids|Sort-Object -Unique).Count -eq 2 -and @($keep|Where-Object {$_ -notin $cleanup.remaining_ids}).Count -eq 0 -and $cleanup.state -ceq 'Off' -and $cleanup.memory_assigned -eq 0 -and $cleanup.raw_file_deletions -eq $false -and @($cleanup.deleted).Count -eq 48) 'Successful exact two-anchor cleanup receipt required.'
Need (-not(Test-Path -LiteralPath (Join-Path $base 'checkpoint-cleanup-20261029\failed.json')) -and -not(Test-Path -LiteralPath (Join-Path $workspace '.lab\hyperv\managed-recovery-fork-20261029')) -and -not(Test-Path -LiteralPath (Join-Path $case 'partial-checkpoint.json'))) 'Cleanup failure, fork or old completed partial receipt requires separate review.'
$failed=Json (Join-Path $case 'preservation-failed.json') '9c8026d3c8b98e87f209aad81bf7af2aee25748c77f0d7b56cec32eb8dfb86d5';$stop=Json (Join-Path $case 'shutdown-intent.json') '8916bac7163342d7f258e63d949d0491c35d0bbd57c26469ae954aa6cd284b47';$terminal=Json (Join-Path $case 'pre-shutdown-terminal.json') '2dc5e0de4b4e841ab0700fca8ef03e2a65fa9e79e2d3922e91a0ef7ef0a68e0c'
Need ($failed.success -eq $false -and $failed.run_id -ceq $run -and $failed.error.Contains('maximum limit of 50 checkpoints has been reached') -and $failed.automatic_retry -eq $false -and $failed.checkpoint_creation_repeated -eq $false -and [guid]$stop.vm_id -eq $id -and [guid]$stop.parent_before_stop -eq $parent -and $stop.workers_absent -eq $true -and $stop.force -eq $false -and $terminal.terminal -eq $true -and $terminal.last_task_result -eq 86 -and $terminal.workers_absent -eq $true -and $terminal.task -ceq ('N2R-ManagedCompact-Interrupt-'+$run) -and $terminal.source_offline -eq $true -and $terminal.source_readonly -eq $false -and $terminal.managed_shadow_disk -eq 6 -and $terminal.shadow_offline -eq $true -and $terminal.shadow_readonly -eq $true) 'Actual terminal86/clean-stop/50-limit failure chronology required.'
$metadataPath=Join-Path $case 'partial-metadata-pins.json';$metadataPin='0d173cdac2cd8caf11b629541d2661ee2eae9cc050b5d4ec9fb7fe16a9b53ef5';$metadata=Json $metadataPath $metadataPin
Need ($metadata.kind -ceq 'closed-managed-partial-metadata-observation' -and $metadata.run_id -ceq $run -and $metadata.controlled_interruption_observed -eq $true -and $metadata.native_exit_observed -eq $true -and $metadata.native_exit -eq 86 -and $metadata.conversion_success -eq $false -and $metadata.interrupt_after_writes -eq 1 -and $metadata.handoff_closed_claimed -eq $false -and $metadata.journal_marker_observed -eq $false -and $metadata.raw_recovery_authorized -eq $false -and @($metadata.documents).Count -eq 25) 'Pinned original controlled86 metadata observation required.'
$documents=@{};$pins=@{};$aggregate=[long]0;foreach($doc in $metadata.documents){Need ($doc.name -cmatch '\A[a-z-]+\.json\z' -and -not$documents.ContainsKey($doc.name)) 'Invalid/duplicate archived JSON leaf.';$path=Join-Path $case ('partial-metadata\'+$doc.name);$m=Get-Item -LiteralPath $path -Force;$aggregate+=$m.Length;Need ($m.Length -eq $doc.bytes -and $aggregate -le 16MB) 'Original25-document archive size differs.';$documents[$doc.name]=Json $path $doc.sha256;$pins[$doc.name]=$doc.sha256}
$worker=$documents['wrapper-worker.json'];$native=$documents['converter-process.json'];$end=$documents['converter-terminal.json'];$controlled=$documents['wrapper-controlled-interruption.json'];$request=$documents['request.json'];$fault=$documents['interruption-intent.json']
Need ($worker.pid -eq 5100 -and $worker.creation_ms -eq 1793232780219 -and $worker.run_id -ceq $run -and $worker.script_sha256 -ceq '91c45dc9fd96b2ad08dfa3f36ac31b8cf817b17a018233cf9e531cb9900cd5e4' -and $native.pid -eq 5004 -and $native.creation_ms -eq 1793232787293 -and $native.parent_pid -eq 5100 -and $native.binary_sha256 -ceq '48094c2b2f3fce10a5b64c5154c1a93837f1415709d611df105bb1a7b3b6735e' -and $native.process_handle_retained_before_wait -eq $true -and $end.native_exit_observed -eq $true -and $end.native_exit -eq 86 -and $controlled.run_id -ceq $run -and $controlled.controlled_interruption_observed -eq $true -and $controlled.conversion_success -eq $false -and $controlled.native_exit_observed -eq $true -and $controlled.native_exit -eq 86 -and $controlled.request_sha256 -ceq $pins['initial-request.json'] -and $request.experiment_id -ceq $run -and $fault.interrupt_after_writes -eq 1 -and $fault.expected_process_exit_code -eq 86 -and $fault.ticket_sha256 -ceq $pins['ticket.json']) 'Actual original5004/5100/controlled one-write metadata differs.'
$stoppedAfter=Utc $stop.utc;$failedAt=Utc $failed.utc;Need ($failedAt -gt $stoppedAfter -and (Utc $cleanup.utc) -gt $failedAt) 'Cleanup must follow the genuine stopped limit failure.'
Import-Module (Join-Path $PSScriptRoot 'Lab.psm1') -Force;$config=Get-LabConfiguration -WorkspaceRoot $workspace;$capacity=Get-LabCapacity -Configuration $config;Need ($capacity.MaximumActualBytes -eq 329374052988 -and $capacity.MinimumFreeBytes -eq 17179869184) 'Fixed50GB epoch/16GiB floor differs.';Assert-LabCapacity -Capacity $capacity -AdditionalBytes 256MB
function Stopped-Guard{
    $vm=Get-VM -Id $id;$all=@(Get-VMSnapshot -VM $vm);$ids=@($all.Id|ForEach-Object {$_.ToString('D')});$system=Get-CimInstance -Namespace root/virtualization/v2 -ClassName Msvm_ComputerSystem -Filter ("Name='"+$id.ToString()+"'") -ErrorAction Stop
    Need ($vm.Name -ceq 'ntfs2refs-streaming-v2-20261027' -and $vm.State.ToString() -ceq 'Off' -and $vm.MemoryAssigned -eq 0 -and $vm.Uptime -eq [TimeSpan]::Zero -and $vm.ParentSnapshotId -eq $parent -and $all.Count -eq 2 -and @($keep|Where-Object {$_ -notin $ids}).Count -eq 0 -and $system.EnabledState -eq 3 -and $null -ne $system.TimeOfLastStateChange) 'Actual stopped partial branch/two retained baselines/native state required.'
    $changed=Utc $system.TimeOfLastStateChange;Need ($changed -ge $stoppedAfter -and $changed -le $failedAt) 'Native last power-state change is outside original clean-stop interval; no unobserved reboot accepted.'
    Need (-not(Test-Path -LiteralPath (Join-Path $workspace '.lab\hyperv\managed-recovery-fork-20261029'))) 'External fork now exists.'
    @{vm_id=$id.ToString();state='Off';memory_assigned=0;parent_id=$vm.ParentSnapshotId.ToString('D');remaining_ids=$ids;last_power_state_change_utc=$changed.ToString('o');no_power_state_change_since_original_clean_stop=$true}
}
$observed=Stopped-Guard
$drives=@(Get-VMHardDiskDrive -VM (Get-VM -Id $id));Need ($drives.Count -eq 6) 'Original six host attachments required.';$chains=@();foreach($drive in $drives){$path=[IO.Path]::GetFullPath($drive.Path);$seen=@{};$chain=@();while($path){Need ($path.StartsWith((Join-Path $workspace '.lab\hyperv\'),[StringComparison]::OrdinalIgnoreCase) -and -not$seen.ContainsKey($path) -and $seen.Count -lt 64) 'Unexpected/cyclic active VHDX chain.';$seen[$path]=$true;$vhd=Get-VHD -Path $path -ErrorAction Stop;$chain+=@{path=$path;parent=$vhd.ParentPath;disk_identifier=[string]$vhd.DiskIdentifier;virtual_bytes=$vhd.Size};$path=if($vhd.ParentPath){[IO.Path]::GetFullPath($vhd.ParentPath)}else{$null}};Need (Test-VHD -Path $drive.Path) 'Hyper-V reports invalid active chain.';$chains+=@{controller=$drive.ControllerNumber;location=$drive.ControllerLocation;chain=$chain}}
New-Item -ItemType Directory -Path $root -ErrorAction Stop|Out-Null;$intentSaved=$false
try{
    Save 'intent.json' @{schema_version=2;kind='partial-preservation-after-authorized-cleanup-intent';run_id=$run;vm_id=$id.ToString();retained_baseline_checkpoint_ids=$keep;cleanup_receipt_sha256=$CleanupReceiptSha256;metadata_pins_sha256=$metadataPin;original_limit_failure_sha256='9c8026d3c8b98e87f209aad81bf7af2aee25748c77f0d7b56cec32eb8dfb86d5';original_limit_failure_preserved=$true;observed=$observed;active_chains_metadata=$chains;capacity=$capacity;forecast_bytes=256MB;script_sha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash.ToLowerInvariant();source_journal_packed_image_data_opened=$false;utc=[DateTime]::UtcNow.ToString('o')};$intentSaved=$true
    $fresh=Stopped-Guard;$parentBefore=[string]$fresh.parent_id;Need (@(Get-VMSnapshot -VM (Get-VM -Id $id)|Where-Object Name -CEQ $name).Count -eq 0) 'New partial checkpoint name already exists.';Assert-LabCapacity -Capacity (Get-LabCapacity -Configuration $config) -AdditionalBytes 256MB
    Save 'checkpoint-create-intent.json' @{schema_version=2;run_id=$run;vm_id=$id.ToString();name=$name;parent_before_creation=$parentBefore;retained_baseline_checkpoint_ids=$keep;cleanup_receipt_sha256=$CleanupReceiptSha256;creation_issued_at_most_once=$true;utc=[DateTime]::UtcNow.ToString('o')};$created=Checkpoint-VM -VM (Get-VM -Id $id) -SnapshotName $name -Passthru -ErrorAction Stop;$direct=if($null -ne $created -and [guid]$created.Id -ne [guid]::Empty){$created.Id.ToString('D')}else{$null};$deadline=[DateTime]::UtcNow.AddSeconds(30)
    do{$vm=Get-VM -Id $id;$all=@(Get-VMSnapshot -VM $vm);$match=@($all|Where-Object Name -CEQ $name);Need ($match.Count -le 1) 'Duplicate new partial name; no retry.';if($match.Count -eq 1 -and $all.Count -eq 3 -and @($keep|Where-Object {$_ -notin @($all.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0){$cp=$match[0].Id.ToString('D');Need (($null -eq $direct -or $cp -ceq $direct) -and $cp -notin $keep -and $vm.State.ToString() -ceq 'Off' -and $vm.MemoryAssigned -eq 0) 'Fresh new partial identity/OFF state differs.';break};if([DateTime]::UtcNow -ge $deadline){throw 'Fresh checkpoint view did not settle in30s; never retry creation.'};Start-Sleep -Milliseconds 500}while($true)
    Save 'partial-checkpoint.json' @{schema_version=2;kind='partial-checkpoint-after-authorized-cleanup-v1';success=$true;run_id=$run;vm_id=$id.ToString();checkpoint_id=$cp;parent_id=$parentBefore;checkpoint_count=3;retained_baseline_checkpoint_ids=$keep;all_retained_baselines_preserved=$true;cleanup_receipt_sha256=$CleanupReceiptSha256;metadata_pins_sha256=$metadataPin;native_exit_observed=$true;native_exit=86;controlled_interruption_observed=$true;interrupt_after_writes=1;conversion_success=$false;journal_marker_observed=$false;handoff_closed_claimed=$false;source_admission_recreated=$false;state='Off';memory_assigned=0;original_checkpoint_limit_failure_preserved=$true;source_journal_packed_image_data_opened=$false;raw_recovery_authorized=$false;scope='Original stopped controlled86 partial state preserved after authorized redundant-checkpoint removal; closed metadata does not recreate admission or replay authority.';utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'partial-checkpoint.json') -Raw
}catch{if($intentSaved -and -not(Test-Path -LiteralPath (Join-Path $root 'failed.json'))){Save 'failed.json' @{schema_version=2;success=$false;run_id=$run;error=$_.Exception.ToString();automatic_retry=$false;checkpoint_creation_repeated=$false;original_limit_failure_preserved=$true;utc=[DateTime]::UtcNow.ToString('o')}};throw}
